// === EMAIL TEMPLATES ===
// Stubs — werden in Schritt 7 durch die polierten Versionen aus
// emails/*.html ersetzt. Struktur und Variablen bleiben identisch:
//   {{FIRSTNAME}} {{FULLNAME}} {{WORKSHOP_NAME}} {{WORKSHOP_DATUM}}
//   {{VORHABEN_6W}} {{NAECHSTER_SCHRITT_72H}}
//   {{TRAINER_NAME}} {{TRAINER_PHOTO_URL}} {{TRAINER_SIGNATURE}}
//   {{QR_CODE_IMAGE}} {{FORM_URL}}
// Nur {{TRAINER_SIGNATURE}} wird als rohes HTML eingesetzt — alle
// anderen Variablen werden HTML-escaped.

const T_BASE_OPEN = '<!doctype html><html lang="de"><body style="font-family:Helvetica,Arial,sans-serif;color:#1A1A1A;line-height:1.6;max-width:560px;margin:0 auto;padding:24px;">';
const T_BASE_CLOSE = '</body></html>';
const T_QUOTE = '<blockquote style="border-left:3px solid #0074DA;padding:8px 16px;margin:16px 0;background:#F2F8FD;">';
const T_QUOTE_CLOSE = '</blockquote>';

const TEMPLATES = {
  thanks_24h:
    T_BASE_OPEN +
    '<p>Hallo {{FIRSTNAME}},</p>' +
    '<p>danke nochmal für deine Teilnahme am Workshop <b>{{WORKSHOP_NAME}}</b>.</p>' +
    '<p>Du hast dir vorgenommen:</p>' +
    T_QUOTE + '{{VORHABEN_6W}}' + T_QUOTE_CLOSE +
    '<p>Und als nächsten Schritt in den nächsten 72 Stunden:</p>' +
    T_QUOTE + '{{NAECHSTER_SCHRITT_72H}}' + T_QUOTE_CLOSE +
    '<p>Beste Grüße<br>{{TRAINER_NAME}}</p>' +
    '<div>{{TRAINER_SIGNATURE}}</div>' +
    T_BASE_CLOSE,

  followup_78h:
    T_BASE_OPEN +
    '<p>Hallo {{FIRSTNAME}},</p>' +
    '<p>vor knapp drei Tagen hast du dir vorgenommen, in den nächsten 72 Stunden diesen Schritt zu gehen:</p>' +
    T_QUOTE + '{{NAECHSTER_SCHRITT_72H}}' + T_QUOTE_CLOSE +
    '<p>Hat es geklappt? Falls ja: super. Falls nicht: kein Drama — frag dich kurz, was im Weg war, und plane den nächsten Versuch.</p>' +
    '<p>Beste Grüße<br>{{TRAINER_NAME}}</p>' +
    '<div>{{TRAINER_SIGNATURE}}</div>' +
    T_BASE_CLOSE,

  final_6w:
    T_BASE_OPEN +
    '<p>Hallo {{FIRSTNAME}},</p>' +
    '<p>vor sechs Wochen — am {{WORKSHOP_DATUM}} — hattest du dir nach unserem Workshop <b>{{WORKSHOP_NAME}}</b> vorgenommen:</p>' +
    T_QUOTE + '{{VORHABEN_6W}}' + T_QUOTE_CLOSE +
    '<p>Wo stehst du heute? Antworte einfach mit einem Klick:</p>' +
    '<p><a href="mailto:{{TRAINER_EMAIL}}?subject=Umsetzung%20Status%20%F0%9F%98%8A&body=Status%3A%20%F0%9F%98%8A%20%E2%80%94%20l%C3%A4uft">😊 Läuft</a> &nbsp; ' +
    '<a href="mailto:{{TRAINER_EMAIL}}?subject=Umsetzung%20Status%20%F0%9F%98%90&body=Status%3A%20%F0%9F%98%90%20%E2%80%94%20teils%20teils">😐 Teils teils</a> &nbsp; ' +
    '<a href="mailto:{{TRAINER_EMAIL}}?subject=Umsetzung%20Status%20%F0%9F%98%9E&body=Status%3A%20%F0%9F%98%9E%20%E2%80%94%20schwierig">😞 Schwierig</a></p>' +
    '<p>Wenn du Unterstützung brauchst, melde dich gerne direkt bei {{TRAINER_NAME}} — einfach auf diese Mail antworten.</p>' +
    '<p>Beste Grüße<br>{{TRAINER_NAME}}</p>' +
    '<div>{{TRAINER_SIGNATURE}}</div>' +
    T_BASE_CLOSE,

  lifo_followup:
    T_BASE_OPEN +
    '<p>Hallo {{FIRSTNAME}},</p>' +
    '<p>du hast nach dem Workshop <b>{{WORKSHOP_NAME}}</b> Interesse an der Weiterarbeit mit deinem LIFO®-Profil signalisiert.</p>' +
    '<p>Falls das noch aktuell ist: lass uns einen 30-min-Termin finden, in dem wir gemeinsam schauen, wie du deine Stärken konkret im Alltag besser nutzen kannst.</p>' +
    '<p><a href="mailto:{{TRAINER_EMAIL}}?subject=LIFO-Weiterarbeit%20{{FIRSTNAME}}">Termin mit {{TRAINER_NAME}} vorschlagen</a></p>' +
    '<p>Beste Grüße<br>{{TRAINER_NAME}}</p>' +
    '<div>{{TRAINER_SIGNATURE}}</div>' +
    T_BASE_CLOSE
};

// === DATEN SAMMELN ===

const emails = $('Query Pending Emails').first().json.results || [];
const subs   = $('Query Submissions').first().json.results   || [];
const wss    = $('Query Workshops').first().json.results     || [];
const trs    = $('Query Trainers').first().json.results      || [];

const subById = Object.fromEntries(subs.map(s => [s._id, s]));
const wsById  = Object.fromEntries(wss.map(w => [w._id, w]));
const trById  = Object.fromEntries(trs.map(t => [t._id, t]));

// === HELPERS ===

function firstLinkedId(link) {
  if (!Array.isArray(link) || link.length === 0) return null;
  const first = link[0];
  if (typeof first === 'string') return first;
  if (first && typeof first === 'object' && first.row_id) return first.row_id;
  return null;
}

function firstName(fullName) {
  return (fullName || '').trim().split(/\s+/)[0] || '';
}

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\n/g, '<br>');
}

function fillTemplate(tpl, vars) {
  return tpl.replace(/\{\{(\w+)\}\}/g, (_, key) => {
    // TRAINER_SIGNATURE bleibt rohes HTML (vom Trainer manuell gepflegt),
    // alle anderen Variablen werden HTML-escaped.
    if (key === 'TRAINER_SIGNATURE') return vars[key] || '';
    return esc(vars[key] || '');
  });
}

function formatDatum(iso) {
  if (!iso) return '';
  const m = String(iso).match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (!m) return iso;
  return `${m[3]}.${m[2]}.${m[1]}`;
}

// === RENDERN ===

const items = [];
for (const email of emails) {
  const subId = firstLinkedId(email.Submission);
  const sub   = subId ? subById[subId] : null;
  if (!sub) {
    items.push({
      json: {
        row_id: email._id,
        skip:   true,
        error:  'submission_not_found'
      }
    });
    continue;
  }
  const wsId = firstLinkedId(sub.Workshop);
  const ws   = wsId ? wsById[wsId] : null;
  const trId = ws ? firstLinkedId(ws.Trainer) : null;
  const tr   = trId ? trById[trId] : null;

  const tpl = TEMPLATES[email.Type] || TEMPLATES.thanks_24h;
  const vars = {
    FIRSTNAME:             firstName(sub.TeilnehmerName),
    FULLNAME:              sub.TeilnehmerName || '',
    WORKSHOP_NAME:         ws ? (ws.Name || '') : '',
    WORKSHOP_DATUM:        ws ? formatDatum(ws.Datum) : '',
    VORHABEN_6W:           sub.Vorhaben6W || '',
    NAECHSTER_SCHRITT_72H: sub.NaechsterSchritt72h || '',
    TRAINER_NAME:          tr ? (tr.Name || '') : 'deinem Trainer',
    TRAINER_EMAIL:         tr ? (tr.Email || 'umsetzung@result.de') : 'umsetzung@result.de',
    TRAINER_PHOTO_URL:     tr ? (tr.FotoUrl || '') : '',
    TRAINER_SIGNATURE:     tr ? (tr.SignatureHtml || '') : '',
    QR_CODE_IMAGE:         ws ? (ws.QrCodeImage || '') : '',
    FORM_URL:              ws ? (ws.FormUrl || '') : ''
  };

  items.push({
    json: {
      row_id:    email._id,
      to:        sub.Email,
      reply_to:  tr ? (tr.Email || 'umsetzung@result.de') : 'umsetzung@result.de',
      subject:   email.Subject || `result. — ${email.Type}`,
      html_body: fillTemplate(tpl, vars)
    }
  });
}

return items;

